def check_graph(n, edges):
    degrees = [0] * n
    edge_set = set()
    for u, v in edges:
        if u < 0 or u >= n or v < 0 or v >= n or u == v:
            return False, "Invalid edge"
        if u > v:
            u, v = v, u
        if (u, v) in edge_set:
            return False, "Duplicate edge"
        edge_set.add((u, v))
        degrees[u] += 1
        degrees[v] += 1

    for d in degrees:
        if d < 3:
            return False, f"Degree too low: {d}"
    return True, degrees

edges = []
for i in range(11):
    edges.append((i, (i + 1) % 11))
    edges.append((i, (i + 2) % 11))

is_valid, result = check_graph(11, edges)
print(f"Valid: {is_valid}, Result: {result}")
print(f"Edges: {edges}")
